def communication_points(periods, start, stop, tolerance=1e-9):
    """Return the ordered communication times within the simulation interval."""
    if stop < start:
        raise ValueError("stop must not precede start")
    if any(period <= 0 for period in periods):
        raise ValueError("communication periods must be positive")
